Arguments: {"code":"const tabId = 1675924496;

const flightsData = await browserjs(tabId, () => {
  // Find all list items or flight card containers
  const items = Array.from(document.querySelectorAll('li'));

  const parsed = [];
  for (const item of items) {
    const text = item.innerText;
    if (!text || !text.includes('$')) continue;

    // Check if it's a flight item (has times like AM/PM and airline/stops)
    if (!text.includes('–') && !text.includes('-')) continue;

    // Let's get the aria-label of the link or button inside if any
    const link = item.querySelector('a') || item.querySelector('[role="link"]') || item.querySelector('button');
    const ariaLabel = item.getAttribute('aria-label') || link?.getAttribute('aria-label') || '';

    parsed.push({
      innerText: text,
      ariaLabel: ariaLabel
    });
  }
  return parsed;
});

console.log(`Parsed ${flightsData.length} items:`);
flightsData.slice(0, 5).forEach((f, i) => {
  console.log(`--- Flight ${i+1} ---`);
  console.log("ariaLabel:", f.ariaLabel);
  console.log("innerText:", f.innerText.replace(/\n+/g, ' | '));
});
